# Consistent hash ring — minimises data movement when nodes are added
import hashlib

class ConsistentHashRing:
    def __init__(self, nodes, replicas=3):
        self._ring = {}
        self._sorted_keys = []
        for node in nodes:
            for r in range(replicas):
                key = self._hash(f'{node}:{r}')
                self._ring[key] = node
                self._sorted_keys.append(key)
        self._sorted_keys.sort()

    def _hash(self, value):
        return int(hashlib.md5(value.encode()).hexdigest(), 16)

    def get_node(self, key):
        h = self._hash(key)
        for ring_key in self._sorted_keys:
            if h <= ring_key:
                return self._ring[ring_key]
        return self._ring[self._sorted_keys[0]]  # wrap around

ring = ConsistentHashRing(['db-1', 'db-2', 'db-3'])
test_keys = ['user:alice', 'user:bob', 'order:1001', 'session:xyz', 'product:42']
for k in test_keys:
    print(f'{k:20s} -> {ring.get_node(k)}')
